-- INFERRED geometry from shipped CharacterFrame.xml/ReputationFrame.xml.
ToggleCharacter("ReputationFrame")
assert(CharacterFrame:IsShown() and ReputationFrame:IsShown())
assert(not PaperDollFrame:IsShown())
assert(PanelTemplates_GetSelectedTab(CharacterFrame) == 3)
local function near(actual, expected, name)
    assert(actual and math.abs(actual - expected) < 0.1,
        name .. ": expected " .. tostring(expected) .. ", got " .. tostring(actual))
end
local left, bottom, width, height = CharacterFrame:GetRect()
near(width, 384, "character width")
near(height, 512, "character height")
near(left, UIParent:GetLeft() + UIParent:GetAttribute("LEFT_OFFSET"), "panel left")
near(bottom + height, UIParent:GetTop() + UIParent:GetAttribute("TOP_OFFSET"), "panel top")
local repLeft, repBottom, repWidth, repHeight = ReputationFrame:GetRect()
near(repLeft, left, "reputation left")
near(repBottom, bottom, "reputation bottom")
near(repWidth, width, "reputation width")
near(repHeight, height, "reputation height")
near(ReputationListScrollFrame:GetWidth(), 296, "scroll width")
near(ReputationListScrollFrame:GetHeight(), 354, "scroll height")
near(ReputationListScrollFrame:GetRight(), left + width - 66, "scroll right")
near(ReputationListScrollFrame:GetTop(), bottom + height - 76, "scroll top")
assert(not ReputationDetailFrame:IsShown(), "detail starts hidden")
near(ReputationDetailFrame:GetWidth(), 212, "detail width")
near(ReputationDetailFrame:GetHeight(), 203, "detail height")
near(ReputationDetailFrame:GetLeft(), left + width - 33, "detail left")
near(ReputationDetailFrame:GetTop(), bottom + height - 28, "detail top")
ReputationDetailFrame:Show()
assert(ReputationDetailFrame:IsShown(), "detail opens")
